INSERT INTO `recipe` (`id`, `title`, `description`, `createdAt`, `updatedAt`, `userId`, `categoryId`) VALUES ('ee45cdaf-716c-4ced-a51d-da7628c3a3ba', 'Shakshuka de tomate asado', 'Huevos pochados en una salsa especiada de tomate y pimiento. Se lleva a la mesa en la misma sartén, con mucho pan.', '2026-11-03 03:10:07.673', '2026-11-03 23:10:07', '88041fc0-8be7-4176-be8f-709ff828f70d', '5a94fc1d-aaed-40de-bc2e-b512ada1516d');
INSERT INTO `recipe` (`id`, `title`, `description`, `createdAt`, `updatedAt`, `userId`, `categoryId`) VALUES ('a13369d8-06d8-47eb-86b9-f187764738e7', 'Paella de marisco de los domingos', 'La receta de mi familia: sofrito paciente, buen caldo y nada de remover. El socarrat se defiende en la mesa.', '2026-11-01 21:10:07.685', '2026-11-03 23:10:07', '5272160d-8de7-48b0-aa99-36dded3c90c7', '4ec3f279-17eb-4668-8d5d-89e35db6d029');
INSERT INTO `recipe` (`id`, `title`, `description`, `createdAt`, `updatedAt`, `userId`, `categoryId`) VALUES ('a4174b4e-79b2-4650-993c-d9735029e724', 'Ramen de miso en casa', 'Un caldo reconfortante que sabe a horas de cocina y se prepara en una tarde. El huevo marinado es obligatorio.', '2026-10-31 19:10:07.690', '2026-11-03 23:10:07', '6f11ec4d-e787-480a-b471-9a1a8bbfa21f', 'b897d47c-7f46-4969-b37e-ebb8673f110b');
INSERT INTO `recipe` (`id`, `title`, `description`, `createdAt`, `updatedAt`, `userId`, `categoryId`) VALUES ('b201319c-9ceb-48a6-ad75-e520e406f899', 'Pizza margarita de masa madre', 'Fermentación de 48 horas en la nevera para una masa ligera y con burbujas. Funciona en un horno doméstico.', '2026-10-30 19:10:07.696', '2026-11-03 23:10:07', '701b80bf-3b53-474f-a293-114d5f12e3eb', '0f3523a9-c51b-4122-b841-acfa0f3370a5');
INSERT INTO `recipe` (`id`, `title`, `description`, `createdAt`, `updatedAt`, `userId`, `categoryId`) VALUES ('de40506d-0b4b-498b-9fa4-f7509fbae339', 'Tarta de queso quemada', 'Tostada por fuera, cremosa por dentro y sin base de galleta. El centro debe temblar cuando sale del horno.', '2026-10-29 13:10:07.702', '2026-11-03 23:10:07', '701b80bf-3b53-474f-a293-114d5f12e3eb', '81a08512-cf35-4093-8450-4be61e2ea61d');
INSERT INTO `recipe` (`id`, `title`, `description`, `createdAt`, `updatedAt`, `userId`, `categoryId`) VALUES ('240c7fa4-aaaf-4648-b7db-769385e7b0bf', 'Tacos de coliflor al pastor', 'Todo el sabor del adobo con piña y una coliflor bien tostada. Hasta quienes dudan repiten.', '2026-10-27 21:10:07.709', '2026-11-03 23:10:07', '88041fc0-8be7-4176-be8f-709ff828f70d', '4ec3f279-17eb-4668-8d5d-89e35db6d029');
INSERT INTO `recipe` (`id`, `title`, `description`, `createdAt`, `updatedAt`, `userId`, `categoryId`) VALUES ('19f4bee7-add6-4594-931b-9e90c13a4023', 'Gazpacho de sandía', 'El gazpacho de siempre con un punto dulce y muy fresco. Listo en diez minutos para los días de calor.', '2026-10-26 05:10:07.714', '2026-11-03 23:10:07', '5272160d-8de7-48b0-aa99-36dded3c90c7', 'b897d47c-7f46-4969-b37e-ebb8673f110b');
INSERT INTO `recipe` (`id`, `title`, `description`, `createdAt`, `updatedAt`, `userId`, `categoryId`) VALUES ('6ff35374-690f-4ea9-a414-215d5f1b66ba', 'Tortitas de arándanos y suero', 'Esponjosas y con los bordes crujientes. El truco es no batir de más y dejar reposar la masa.', '2026-10-24 03:10:07.720', '2026-11-03 23:10:07', '88041fc0-8be7-4176-be8f-709ff828f70d', '5a94fc1d-aaed-40de-bc2e-b512ada1516d');
INSERT INTO `recipe` (`id`, `title`, `description`, `createdAt`, `updatedAt`, `userId`, `categoryId`) VALUES ('56e26a34-e34c-47ac-a99d-87ec289b2901', 'Poke de salmón y mango', 'Un bol fresco y lleno de texturas para una comida rápida. Marinar el salmón solo diez minutos marca la diferencia.', '2026-10-21 15:10:07.727', '2026-11-03 23:10:07', '6f11ec4d-e787-480a-b471-9a1a8bbfa21f', 'eda48d85-8876-49aa-805d-ff6706cb8e73');
INSERT INTO `recipe` (`id`, `title`, `description`, `createdAt`, `updatedAt`, `userId`, `categoryId`) VALUES ('4c054f46-e26f-4c2d-aaba-281ba09e2034', 'Galletas de chocolate y sal', 'Crujientes por el borde y blandas en el centro. Dejar la masa en la nevera una noche cambia el resultado.', '2026-10-18 07:10:07.732', '2026-11-03 23:10:07', '701b80bf-3b53-474f-a293-114d5f12e3eb', '81a08512-cf35-4093-8450-4be61e2ea61d');
