INSERT INTO `preparations` (`id`, `preparation`, `position`, `recipeId`) VALUES ('89a2d6de-84cf-4d5c-8668-78b2408d5933', 'Asa los tomates y los pimientos a 220 °C durante 25 minutos, hasta que la piel se tueste. Pélalos y trocéalos.', 0, 'ee45cdaf-716c-4ced-a51d-da7628c3a3ba');
INSERT INTO `preparations` (`id`, `preparation`, `position`, `recipeId`) VALUES ('763fbc4b-25e3-4948-9790-ec044ee66c41', 'Pocha la cebolla en aceite a fuego medio. Añade el ajo, el comino y el pimentón, y remueve un minuto.', 1, 'ee45cdaf-716c-4ced-a51d-da7628c3a3ba');
INSERT INTO `preparations` (`id`, `preparation`, `position`, `recipeId`) VALUES ('3b5962e9-b10e-4d3f-96b6-fb9a7de32dd1', 'Incorpora el tomate y el pimiento, sala y deja reducir 15 minutos hasta que la salsa espese.', 2, 'ee45cdaf-716c-4ced-a51d-da7628c3a3ba');
INSERT INTO `preparations` (`id`, `preparation`, `position`, `recipeId`) VALUES ('cfa2f7f7-5ea0-4433-9526-fc268ef93acc', 'Abre huecos en la salsa, casca un huevo en cada uno y tapa hasta que la clara cuaje y la yema siga líquida.', 3, 'ee45cdaf-716c-4ced-a51d-da7628c3a3ba');
INSERT INTO `preparations` (`id`, `preparation`, `position`, `recipeId`) VALUES ('68a58957-4e54-4833-a9f0-ec84929c87e8', 'Termina con cilantro picado y sirve en la sartén con pan tostado.', 4, 'ee45cdaf-716c-4ced-a51d-da7628c3a3ba');
INSERT INTO `preparations` (`id`, `preparation`, `position`, `recipeId`) VALUES ('af049221-db45-4c95-a883-1b185344ddb8', 'Marca las gambas en la paella con aceite caliente y resérvalas.', 0, 'a13369d8-06d8-47eb-86b9-f187764738e7');
INSERT INTO `preparations` (`id`, `preparation`, `position`, `recipeId`) VALUES ('066e6a7e-c4a7-4731-b5f3-b86cd6ddc93f', 'Dora la sepia troceada 5 minutos, añade el tomate rallado y sofríe hasta que pierda toda el agua.', 1, 'a13369d8-06d8-47eb-86b9-f187764738e7');
INSERT INTO `preparations` (`id`, `preparation`, `position`, `recipeId`) VALUES ('6a679065-a18b-4018-b213-6752531bf6ee', 'Agrega el arroz, nacara un minuto y vierte el caldo caliente con el azafrán. Reparte bien y no vuelvas a remover.', 2, 'a13369d8-06d8-47eb-86b9-f187764738e7');
INSERT INTO `preparations` (`id`, `preparation`, `position`, `recipeId`) VALUES ('59dce652-0f7a-4ef1-bed2-fa872a54cfaf', 'Cuece 10 minutos a fuego fuerte y 8 a fuego suave. A mitad de cocción coloca los mejillones y las gambas.', 3, 'a13369d8-06d8-47eb-86b9-f187764738e7');
INSERT INTO `preparations` (`id`, `preparation`, `position`, `recipeId`) VALUES ('3e96e5c4-d1bf-48f0-8fd6-8396b577f56f', 'Sube el fuego el último minuto para el socarrat. Reposa 5 minutos tapada con un paño y sirve con limón.', 4, 'a13369d8-06d8-47eb-86b9-f187764738e7');
INSERT INTO `preparations` (`id`, `preparation`, `position`, `recipeId`) VALUES ('065a9f54-a8cf-4b24-b089-5dc0ea240b20', 'Cuece los huevos 6 minutos y medio, enfríalos y márinalos en soja y agua un mínimo de dos horas.', 0, 'a4174b4e-79b2-4650-993c-d9735029e724');
INSERT INTO `preparations` (`id`, `preparation`, `position`, `recipeId`) VALUES ('91f8c209-64f1-4ae4-a1da-020a82b49a77', 'Calienta el caldo sin que llegue a hervir. Disuelve el miso y la soja en un cazo aparte con un poco de caldo y devuélvelo a la olla.', 1, 'a4174b4e-79b2-4650-993c-d9735029e724');
INSERT INTO `preparations` (`id`, `preparation`, `position`, `recipeId`) VALUES ('3f8f8f3b-3d42-4dc5-8d12-a6e261130acd', 'Cuece los fideos según el paquete, escúrrelos y repártelos en cuatro boles.', 2, 'a4174b4e-79b2-4650-993c-d9735029e724');
INSERT INTO `preparations` (`id`, `preparation`, `position`, `recipeId`) VALUES ('22f89bb2-83d2-46e0-8717-642dbf290d6f', 'Vierte el caldo muy caliente sobre los fideos.', 3, 'a4174b4e-79b2-4650-993c-d9735029e724');
INSERT INTO `preparations` (`id`, `preparation`, `position`, `recipeId`) VALUES ('4e1e9e25-7762-40d4-be1e-c33e32fe689f', 'Corona con medio huevo, cebolleta, maíz, nori y unas gotas de aceite de sésamo.', 4, 'a4174b4e-79b2-4650-993c-d9735029e724');
INSERT INTO `preparations` (`id`, `preparation`, `position`, `recipeId`) VALUES ('e8b52aa7-8342-4044-b600-b0282f56d3c6', 'Mezcla la harina con el agua y deja reposar 30 minutos. Añade la masa madre y la sal, y amasa hasta que quede lisa.', 0, 'b201319c-9ceb-48a6-ad75-e520e406f899');
INSERT INTO `preparations` (`id`, `preparation`, `position`, `recipeId`) VALUES ('a15cf4eb-b0c2-4ae7-bfab-213207b30e7c', 'Fermenta 3 horas con dos pliegues y guarda la masa en la nevera 48 horas, bien tapada.', 1, 'b201319c-9ceb-48a6-ad75-e520e406f899');
INSERT INTO `preparations` (`id`, `preparation`, `position`, `recipeId`) VALUES ('2ec88df1-ac5f-4abf-9ecc-02ecb67f9a59', 'Divide en cuatro bolas y déjalas atemperar 2 horas. Precalienta el horno al máximo con una piedra o bandeja dentro.', 2, 'b201319c-9ceb-48a6-ad75-e520e406f899');
INSERT INTO `preparations` (`id`, `preparation`, `position`, `recipeId`) VALUES ('3ccc4a71-d360-4120-b6c6-d7aa0b8cad01', 'Estira con las manos, sin rodillo. Cubre con tomate y hornea 6 minutos; añade la mozzarella y hornea 2 más.', 3, 'b201319c-9ceb-48a6-ad75-e520e406f899');
INSERT INTO `preparations` (`id`, `preparation`, `position`, `recipeId`) VALUES ('ccda65fd-fc21-44a6-8889-5af120dba088', 'Saca del horno y termina con albahaca y un hilo de aceite.', 4, 'b201319c-9ceb-48a6-ad75-e520e406f899');
INSERT INTO `preparations` (`id`, `preparation`, `position`, `recipeId`) VALUES ('37302d5a-0754-46df-a902-45aedd6f71b9', 'Precalienta el horno a 220 °C y forra un molde de 24 cm con papel de horno arrugado.', 0, 'de40506d-0b4b-498b-9fa4-f7509fbae339');
INSERT INTO `preparations` (`id`, `preparation`, `position`, `recipeId`) VALUES ('8dbd5657-45a3-433a-b6e8-dc3daa017f73', 'Bate el queso con el azúcar y la sal hasta que quede sin grumos. Añade los huevos de uno en uno.', 1, 'de40506d-0b4b-498b-9fa4-f7509fbae339');
INSERT INTO `preparations` (`id`, `preparation`, `position`, `recipeId`) VALUES ('be51200f-a4fe-4d38-bb0a-acfa9a94de9f', 'Incorpora la nata y la harina tamizada, y mezcla justo hasta integrar.', 2, 'de40506d-0b4b-498b-9fa4-f7509fbae339');
INSERT INTO `preparations` (`id`, `preparation`, `position`, `recipeId`) VALUES ('dab8ea66-9509-4a27-b4da-22483a358d30', 'Hornea unos 40 minutos, hasta que la superficie esté muy oscura y el centro aún tiemble.', 3, 'de40506d-0b4b-498b-9fa4-f7509fbae339');
INSERT INTO `preparations` (`id`, `preparation`, `position`, `recipeId`) VALUES ('42ddf215-54d5-400b-849d-b4409830593e', 'Deja enfriar a temperatura ambiente y lleva a la nevera al menos 4 horas antes de cortarla.', 4, 'de40506d-0b4b-498b-9fa4-f7509fbae339');
INSERT INTO `preparations` (`id`, `preparation`, `position`, `recipeId`) VALUES ('4d80a83f-50f7-4b4e-9de5-5b17b9fc82c8', 'Hidrata los chiles en agua caliente y tritúralos con el ajo, el orégano y el zumo de lima.', 0, '240c7fa4-aaaf-4648-b7db-769385e7b0bf');
INSERT INTO `preparations` (`id`, `preparation`, `position`, `recipeId`) VALUES ('96786cde-a25b-446d-858c-d16e0cf4f5ef', 'Trocea la coliflor en ramilletes, mézclala con el adobo y hornea 30 minutos a 210 °C, removiendo a mitad.', 1, '240c7fa4-aaaf-4648-b7db-769385e7b0bf');
INSERT INTO `preparations` (`id`, `preparation`, `position`, `recipeId`) VALUES ('b9e477ae-bd0f-43a3-bc60-1a90f670d783', 'Dora la piña en dados en una sartén muy caliente, hasta que caramelice.', 2, '240c7fa4-aaaf-4648-b7db-769385e7b0bf');
INSERT INTO `preparations` (`id`, `preparation`, `position`, `recipeId`) VALUES ('676d6e51-447b-4cb5-91ca-ef57f5f44b45', 'Calienta las tortillas en la sartén seca y rellénalas con la coliflor y la piña.', 3, '240c7fa4-aaaf-4648-b7db-769385e7b0bf');
INSERT INTO `preparations` (`id`, `preparation`, `position`, `recipeId`) VALUES ('e377d214-1dad-495b-a307-99d72090e910', 'Sirve con cebolla morada, cilantro y unas gotas de lima.', 4, '240c7fa4-aaaf-4648-b7db-769385e7b0bf');
INSERT INTO `preparations` (`id`, `preparation`, `position`, `recipeId`) VALUES ('b0711b28-9d3a-4a95-bf34-c88732022ef6', 'Trocea el tomate, la sandía, el pepino y el pimiento, y ponlos en el vaso de la batidora con el ajo.', 0, '19f4bee7-add6-4594-931b-9e90c13a4023');
INSERT INTO `preparations` (`id`, `preparation`, `position`, `recipeId`) VALUES ('9de955ad-b6fa-4bb8-86f1-43359ea01a74', 'Tritura a máxima potencia durante 2 minutos.', 1, '19f4bee7-add6-4594-931b-9e90c13a4023');
INSERT INTO `preparations` (`id`, `preparation`, `position`, `recipeId`) VALUES ('e5428f2b-d6c9-48dd-86a2-8130a9f14014', 'Añade el vinagre y la sal, y agrega el aceite en un hilo sin dejar de batir para emulsionar.', 2, '19f4bee7-add6-4594-931b-9e90c13a4023');
INSERT INTO `preparations` (`id`, `preparation`, `position`, `recipeId`) VALUES ('ff007b96-45a8-4b2c-9221-ccd6e6c86c22', 'Cuela si lo quieres más fino y enfría en la nevera un mínimo de una hora.', 3, '19f4bee7-add6-4594-931b-9e90c13a4023');
INSERT INTO `preparations` (`id`, `preparation`, `position`, `recipeId`) VALUES ('5278fdc1-0d91-4495-a056-1a4df10f3fae', 'Sirve bien frío con dados de sandía y pepino por encima.', 4, '19f4bee7-add6-4594-931b-9e90c13a4023');
INSERT INTO `preparations` (`id`, `preparation`, `position`, `recipeId`) VALUES ('e9d0e8a1-7606-4b70-a6e7-c980ce027534', 'Mezcla la harina, el azúcar, la levadura y una pizca de sal en un bol.', 0, '6ff35374-690f-4ea9-a414-215d5f1b66ba');
INSERT INTO `preparations` (`id`, `preparation`, `position`, `recipeId`) VALUES ('1ee3c975-69f2-427f-b4ca-d689695f3e23', 'En otro bol, bate el suero, los huevos y la mantequilla. Únelo a los secos con pocas vueltas: deben quedar grumos.', 1, '6ff35374-690f-4ea9-a414-215d5f1b66ba');
INSERT INTO `preparations` (`id`, `preparation`, `position`, `recipeId`) VALUES ('34d6cdbe-caac-45af-8ed1-24e0beda0a7b', 'Deja reposar la masa 15 minutos.', 2, '6ff35374-690f-4ea9-a414-215d5f1b66ba');
INSERT INTO `preparations` (`id`, `preparation`, `position`, `recipeId`) VALUES ('d34f4954-3ebb-45eb-9786-98d08fa4dcb1', 'Vierte un cucharón en una sartén con mantequilla a fuego medio y reparte arándanos. Da la vuelta cuando salgan burbujas.', 3, '6ff35374-690f-4ea9-a414-215d5f1b66ba');
INSERT INTO `preparations` (`id`, `preparation`, `position`, `recipeId`) VALUES ('d63a65ec-89ed-4b90-8ae6-80e7a9ecaea9', 'Apila las tortitas y termina con más arándanos y sirope.', 4, '6ff35374-690f-4ea9-a414-215d5f1b66ba');
INSERT INTO `preparations` (`id`, `preparation`, `position`, `recipeId`) VALUES ('e833ba90-6202-4102-8453-0a1c5f7bbfa5', 'Cuece el arroz, aderézalo con un poco de vinagre de arroz y déjalo templar.', 0, '56e26a34-e34c-47ac-a99d-87ec289b2901');
INSERT INTO `preparations` (`id`, `preparation`, `position`, `recipeId`) VALUES ('104f82ba-d9ed-4441-87ba-96b6c03021a7', 'Corta el salmón en dados y márinalo 10 minutos con la soja y el aceite de sésamo.', 1, '56e26a34-e34c-47ac-a99d-87ec289b2901');
INSERT INTO `preparations` (`id`, `preparation`, `position`, `recipeId`) VALUES ('0383bf1c-df8b-44b3-9a5c-6bec7e1b6778', 'Corta el mango, el aguacate y el pepino en dados o láminas.', 2, '56e26a34-e34c-47ac-a99d-87ec289b2901');
INSERT INTO `preparations` (`id`, `preparation`, `position`, `recipeId`) VALUES ('99423963-f841-467e-bc37-283c41a28e97', 'Pon el arroz en la base de cada bol y coloca los ingredientes por secciones.', 3, '56e26a34-e34c-47ac-a99d-87ec289b2901');
INSERT INTO `preparations` (`id`, `preparation`, `position`, `recipeId`) VALUES ('df065963-2076-4ab8-901a-d8de4f770c63', 'Termina con las semillas de sésamo y el resto de la marinada.', 4, '56e26a34-e34c-47ac-a99d-87ec289b2901');
INSERT INTO `preparations` (`id`, `preparation`, `position`, `recipeId`) VALUES ('f9302f3a-0050-4711-9564-3046f0b8349f', 'Tuesta la mantequilla en un cazo hasta que huela a avellana y deja que se temple.', 0, '4c054f46-e26f-4c2d-aaba-281ba09e2034');
INSERT INTO `preparations` (`id`, `preparation`, `position`, `recipeId`) VALUES ('38df54ed-888c-468f-8949-0fa2102d8555', 'Bátela con los dos azúcares y añade los huevos de uno en uno.', 1, '4c054f46-e26f-4c2d-aaba-281ba09e2034');
INSERT INTO `preparations` (`id`, `preparation`, `position`, `recipeId`) VALUES ('15fc752e-7462-457b-a3ca-71d45f7f1837', 'Incorpora la harina con el bicarbonato y después el chocolate. Enfría la masa en la nevera 12 horas.', 2, '4c054f46-e26f-4c2d-aaba-281ba09e2034');
INSERT INTO `preparations` (`id`, `preparation`, `position`, `recipeId`) VALUES ('c81d8670-52eb-4840-94fd-d1e916a5bbd8', 'Forma bolas, sepáralas bien en la bandeja y hornea 11 minutos a 180 °C.', 3, '4c054f46-e26f-4c2d-aaba-281ba09e2034');
INSERT INTO `preparations` (`id`, `preparation`, `position`, `recipeId`) VALUES ('488cd5cc-0608-4f30-97d4-c82031197f57', 'Pon unas escamas de sal al sacarlas y déjalas reposar 10 minutos antes de moverlas.', 4, '4c054f46-e26f-4c2d-aaba-281ba09e2034');
