INSERT INTO `comment` (`id`, `text`, `recipeId`, `createdAt`, `userId`) VALUES ('f70a7ebe-2ae0-4c3f-8a8a-b121d591d0fb', 'La he hecho este finde con los últimos tomates del huerto. Asarlos antes cambia por completo la salsa.', 'ee45cdaf-716c-4ced-a51d-da7628c3a3ba', '2026-11-03 14:10:07.742', '5272160d-8de7-48b0-aa99-36dded3c90c7');
INSERT INTO `comment` (`id`, `text`, `recipeId`, `createdAt`, `userId`) VALUES ('4da24789-f299-413d-bf1d-0ef4b5263ac5', 'Le añadí un poco de feta al final y quedó increíble.', 'ee45cdaf-716c-4ced-a51d-da7628c3a3ba', '2026-11-03 19:10:07.743', '6f11ec4d-e787-480a-b471-9a1a8bbfa21f');
INSERT INTO `comment` (`id`, `text`, `recipeId`, `createdAt`, `userId`) VALUES ('cc0f9cba-3964-45b4-ba6b-b086c0ae938a', 'Por fin entiendo lo de no remover. Primer socarrat de mi vida.', 'a13369d8-06d8-47eb-86b9-f187764738e7', '2026-11-02 17:10:07.743', '701b80bf-3b53-474f-a293-114d5f12e3eb');
INSERT INTO `comment` (`id`, `text`, `recipeId`, `createdAt`, `userId`) VALUES ('204eee28-f358-4cc1-a6df-4e523e2f7df6', '¿El caldo lo haces con cabezas de gamba? Huele a gloria solo de leerlo.', 'a13369d8-06d8-47eb-86b9-f187764738e7', '2026-11-03 01:10:07.743', '88041fc0-8be7-4176-be8f-709ff828f70d');
INSERT INTO `comment` (`id`, `text`, `recipeId`, `createdAt`, `userId`) VALUES ('ac4face4-deb1-4464-8cc0-d6cdc1477b49', 'Sí, Nora: cabezas de gamba, un puerro y una hora a fuego lento.', 'a13369d8-06d8-47eb-86b9-f187764738e7', '2026-11-03 02:10:07.743', '5272160d-8de7-48b0-aa99-36dded3c90c7');
INSERT INTO `comment` (`id`, `text`, `recipeId`, `createdAt`, `userId`) VALUES ('d7321e3f-a7d9-47bb-b5cc-793bbc2368f4', 'El huevo marinado merece la pena. Dejé los míos toda la noche.', 'a4174b4e-79b2-4650-993c-d9735029e724', '2026-11-02 07:10:07.743', '5272160d-8de7-48b0-aa99-36dded3c90c7');
INSERT INTO `comment` (`id`, `text`, `recipeId`, `createdAt`, `userId`) VALUES ('6ac9f210-c552-444e-877b-5fccbccdc1f5', 'Con piedra precalentada y al máximo, la base sale crujiente. Gracias por el truco.', 'b201319c-9ceb-48a6-ad75-e520e406f899', '2026-11-01 11:10:07.743', '6f11ec4d-e787-480a-b471-9a1a8bbfa21f');
INSERT INTO `comment` (`id`, `text`, `recipeId`, `createdAt`, `userId`) VALUES ('1fc29e49-d699-4d7c-9fc7-5d8d81eda54f', 'Parecía poco hecha al sacarla, pero al día siguiente estaba perfecta.', 'de40506d-0b4b-498b-9fa4-f7509fbae339', '2026-11-01 01:10:07.743', '88041fc0-8be7-4176-be8f-709ff828f70d');
INSERT INTO `comment` (`id`, `text`, `recipeId`, `createdAt`, `userId`) VALUES ('2a55be7d-8003-40e0-9a35-140561e053da', 'Me salió menos dorada que la tuya. La próxima vez, cinco minutos más.', 'de40506d-0b4b-498b-9fa4-f7509fbae339', '2026-11-01 16:10:07.743', '5272160d-8de7-48b0-aa99-36dded3c90c7');
INSERT INTO `comment` (`id`, `text`, `recipeId`, `createdAt`, `userId`) VALUES ('29e996c0-0428-45a6-b110-48db3e05217f', 'No como carne desde hace poco y estos me han reconciliado con los tacos.', '240c7fa4-aaaf-4648-b7db-769385e7b0bf', '2026-10-31 05:10:07.743', '701b80bf-3b53-474f-a293-114d5f12e3eb');
INSERT INTO `comment` (`id`, `text`, `recipeId`, `createdAt`, `userId`) VALUES ('498db42b-0a71-4055-b90d-e6c79d6fd0e9', 'Los grumos dan miedo, pero tenías razón: salen muy esponjosas.', '6ff35374-690f-4ea9-a414-215d5f1b66ba', '2026-10-29 23:10:07.743', '6f11ec4d-e787-480a-b471-9a1a8bbfa21f');
INSERT INTO `comment` (`id`, `text`, `recipeId`, `createdAt`, `userId`) VALUES ('e27be015-5e64-4c91-a69d-d5a1701a2a63', 'La noche en la nevera es imprescindible. Probé sin esperar y no tienen nada que ver.', '4c054f46-e26f-4c2d-aaba-281ba09e2034', '2026-10-28 17:10:07.743', '88041fc0-8be7-4176-be8f-709ff828f70d');
