CREATE DATABASE IF NOT EXISTS `recetas_demo` CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE `recetas_demo`;
SET NAMES utf8mb4;
SET FOREIGN_KEY_CHECKS = 0;

DROP TABLE IF EXISTS `user`;
DROP TABLE IF EXISTS `category`;
DROP TABLE IF EXISTS `recipe`;
DROP TABLE IF EXISTS `image`;
DROP TABLE IF EXISTS `ingredients`;
DROP TABLE IF EXISTS `preparations`;
DROP TABLE IF EXISTS `hashtags`;
DROP TABLE IF EXISTS `comment`;
DROP TABLE IF EXISTS `rating`;
DROP TABLE IF EXISTS `post`;

CREATE TABLE `image` (`id` varchar(36) NOT NULL, `url` varchar(255) NOT NULL, `position` int NOT NULL DEFAULT '0', `createdAt` datetime(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6), `updatedAt` datetime(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6), `recipeId` varchar(36) NULL, PRIMARY KEY (`id`)) ENGINE=InnoDB;
CREATE TABLE `ingredients` (`id` varchar(36) NOT NULL, `ingredient` varchar(255) NOT NULL, `position` int NOT NULL DEFAULT '0', `recipeId` varchar(36) NULL, PRIMARY KEY (`id`)) ENGINE=InnoDB;
CREATE TABLE `preparations` (`id` varchar(36) NOT NULL, `preparation` varchar(255) NOT NULL, `position` int NOT NULL DEFAULT '0', `recipeId` varchar(36) NULL, PRIMARY KEY (`id`)) ENGINE=InnoDB;
CREATE TABLE `hashtags` (`id` varchar(36) NOT NULL, `hashtag` varchar(255) NOT NULL, `recipeId` varchar(36) NULL, PRIMARY KEY (`id`)) ENGINE=InnoDB;
CREATE TABLE `recipe` (`id` varchar(36) NOT NULL, `title` varchar(255) NOT NULL, `description` varchar(255) NOT NULL, `createdAt` datetime(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6), `updatedAt` datetime(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6), `userId` varchar(36) NULL, `categoryId` varchar(36) NULL, PRIMARY KEY (`id`)) ENGINE=InnoDB;
CREATE TABLE `post` (`id` varchar(36) NOT NULL, `caption` text NOT NULL, `image` varchar(255) NOT NULL, `userId` varchar(36) NOT NULL, `createdAt` datetime(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6), `recipeId` varchar(36) NULL, PRIMARY KEY (`id`)) ENGINE=InnoDB;
CREATE TABLE `user` (`id` varchar(36) NOT NULL, `name` varchar(255) NOT NULL, `email` varchar(255) NOT NULL, `password` varchar(255) NOT NULL, `role` varchar(20) NOT NULL DEFAULT 'user', `isBlocked` tinyint NOT NULL DEFAULT 0, `bio` text NULL, `avatar` varchar(255) NULL, `createdAt` datetime(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6), UNIQUE INDEX `IDX_e12875dfb3b1d92d7d7c5377e2` (`email`), PRIMARY KEY (`id`)) ENGINE=InnoDB;
CREATE TABLE `category` (`id` varchar(36) NOT NULL, `name` varchar(255) NOT NULL, `createdAt` datetime(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6), `updatedAt` datetime(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6), `userId` varchar(36) NULL, PRIMARY KEY (`id`)) ENGINE=InnoDB;
CREATE TABLE `comment` (`id` varchar(36) NOT NULL, `text` text NOT NULL, `recipeId` varchar(36) NOT NULL, `createdAt` datetime(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6), `userId` varchar(36) NULL, PRIMARY KEY (`id`)) ENGINE=InnoDB;
CREATE TABLE `rating` (`id` varchar(36) NOT NULL, `value` int NOT NULL, `recipeId` varchar(36) NOT NULL, `userId` varchar(36) NOT NULL, `createdAt` datetime(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6), `updatedAt` datetime(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6), UNIQUE INDEX `IDX_3109e2810885835673d32de5b2` (`userId`, `recipeId`), PRIMARY KEY (`id`)) ENGINE=InnoDB;

ALTER TABLE `image` ADD CONSTRAINT `FK_4f43c43cadc0bbaae9e81831f38` FOREIGN KEY (`recipeId`) REFERENCES `recipe`(`id`) ON DELETE CASCADE ON UPDATE NO ACTION;
